const SPORT_ORDER = ["tennis","bball","wbball","baseball","nhl","mma","nascar","nfl","cfl","epl","cfb","cbb","big3","boxing","soccer","kbo","lax","worldcup","mvp","npb","ufl","indycar"];

const REF_LABELS = {
  tennis: "Tennis — official breakdown",
  mma: "MMA — official breakdown",
  wnba: "WNBA — official breakdown",
  mlb: "MLB — Batter & Pitcher breakdown (stitched)",
  nba: "NBA — official breakdown",
  nhl: "NHL — Skater & Goalie breakdown (stitched)",
  nascar: "NASCAR — full finish-position table (stitched from 3 screenshots)",
  nfl: "NFL — Offense & Kicker breakdown (stitched)",
  cfl: "CFL — Offense & Kicker breakdown (stitched)",
  epl: "EPL — Outfield & Goalie breakdown (stitched)",
  cfb: "CFB — Offense & Kicker breakdown (stitched)",
  cbb: "CBB — official breakdown",
  big3: "BIG3 — official scoring chart",
  boxing: "Boxing — In-Fight & Post-Fight breakdown",
  soccer: "Soccer — Outfield & Goalie breakdown (stitched)",
  kbo: "KBO — Batter & Pitcher breakdown (stitched)",
  lax: "LAX — PrizePicks stat type breakdown",
  worldcup: "World Cup — Outfield & Goalie breakdown (stitched)",
  mvp: "MVP — MMA & Boxing breakdown (stitched)",
  npb: "NPB — Hitter & Pitcher breakdown (stitched)",
  ufl: "UFL — Offense & Kicker breakdown (stitched)",
  indycar: "INDYCAR — full finish-position table (stitched seamlessly)"
};


(function(){
  let currentSportKey = "tennis";
  let currentLeagueIdx = 0;
  let currentMode = null; // for baseball / nhl

  // overrides[sportKey|mode] = { statKey: { pts, count } }
  const overrides = {};

  function stateId(){
    return currentSportKey + (currentMode ? ("::" + currentMode) : "");
  }

  function getSport(){ return SPORTS[currentSportKey]; }

  function getStats(){
    const s = getSport();
    if (s.statsByMode){
      return s.statsByMode[currentMode || s.modes[0]];
    }
    return s.stats;
  }

  function getStateBucket(){
    const id = stateId();
    if (!overrides[id]) overrides[id] = {};
    return overrides[id];
  }

  function getStatValue(statKey, field, fallback){
    const bucket = getStateBucket();
    if (bucket[statKey] && bucket[statKey][field] !== undefined) return bucket[statKey][field];
    return fallback;
  }

  function setStatValue(statKey, field, value){
    const bucket = getStateBucket();
    if (!bucket[statKey]) bucket[statKey] = {};
    bucket[statKey][field] = value;
  }

  function fmtNum(n){
    const r = Math.round(n*100)/100;
    return r.toString();
  }

  function pluralPt(n){
    return Math.abs(n) === 1 ? "pt" : "pts";
  }

  // ---------- Sport rail ----------
  function renderRail(){
    const rail = document.getElementById("sportRail");
    rail.innerHTML = "";
    SPORT_ORDER.forEach(key => {
      const s = SPORTS[key];
      const chip = document.createElement("button");
      chip.className = "chip" + (key === currentSportKey ? " active" : "");
      chip.textContent = s.name;
      chip.dataset.key = key;
      chip.onclick = () => {
        currentSportKey = key;
        currentLeagueIdx = 0;
        const sp = getSport();
        currentMode = sp.modes ? sp.modes[0] : null;
        renderAll();
      };
      rail.appendChild(chip);
    });
  }

  // ---------- Controls row (league select / mode toggle / reset) ----------
  function renderControls(){
    const row = document.getElementById("controlsRow");
    row.innerHTML = "";
    const sport = getSport();

    if (sport.leagues){
      const sel = document.createElement("select");
      sel.className = "league-select";
      sport.leagues.forEach((lg, i) => {
        const opt = document.createElement("option");
        opt.value = i; opt.textContent = lg;
        if (i === currentLeagueIdx) opt.selected = true;
        sel.appendChild(opt);
      });
      sel.onchange = (e) => { currentLeagueIdx = parseInt(e.target.value, 10); renderSpielTag(); recompute(); };
      row.appendChild(sel);
    }

    if (sport.modes){
      const toggle = document.createElement("div");
      toggle.className = "mode-toggle";
      sport.modes.forEach(m => {
        const btn = document.createElement("button");
        btn.textContent = m;
        btn.className = (m === currentMode) ? "active" : "";
        btn.onclick = () => { currentMode = m; renderAll(); };
        toggle.appendChild(btn);
      });
      row.appendChild(toggle);
    }

    const resetBtn = document.createElement("button");
    resetBtn.className = "reset-btn";
    resetBtn.textContent = "↺ reset stat sheet";
    resetBtn.onclick = () => { delete overrides[stateId()]; renderAll(); };
    row.appendChild(resetBtn);
  }

  function currentLeagueLabel(){
    const sport = getSport();
    if (sport.leagues) return sport.leagues[currentLeagueIdx];
    if (sport.modes) return (currentMode || sport.modes[0]);
    return sport.name;
  }

  function renderSpielTag(){
    document.getElementById("spielTag").textContent = currentLeagueLabel();
  }

  // ---------- Reference button ----------
  function renderRefButton(){
    const btn = document.getElementById("openRef");
    const sport = getSport();
    if (sport.ref && REF_IMAGES[sport.ref]){
      btn.style.display = "inline-flex";
      btn.innerHTML = `📇 Reference card <span style="color:var(--text-faint)">— ${sport.name} format</span>`;
    } else {
      btn.style.display = "none";
    }
  }

  function openRefModal(){
    const sport = getSport();
    if (!sport.ref || !REF_IMAGES[sport.ref]) return;
    const img = document.getElementById("refImg");
    img.src = "data:image/png;base64," + REF_IMAGES[sport.ref];
    document.getElementById("refCaption").textContent = REF_LABELS[sport.ref] || sport.name;
    document.getElementById("refModal").classList.add("show");
  }

  // ---------- Stat table ----------
  function renderStatTable(){
    const sport = getSport();
    document.getElementById("statTitle").textContent = sport.name + " — Stat Sheet";
    const noteEl = document.getElementById("squaresNote");
    if (sport.squaresNote){
      noteEl.textContent = Array.isArray(sport.squaresNote) ? sport.squaresNote.join("\n") : sport.squaresNote;
      noteEl.style.display = "flex";
    } else {
      noteEl.style.display = "none";
    }
    const body = document.getElementById("statBody");
    body.innerHTML = "";
    const stats = getStats();
    let lastGroup = undefined;

    stats.forEach(stat => {
      if (stat.group !== undefined && stat.group !== lastGroup){
        const groupTr = document.createElement("tr");
        groupTr.className = "group-row";
        const td = document.createElement("td");
        td.colSpan = 4;
        td.textContent = stat.group;
        groupTr.appendChild(td);
        body.appendChild(groupTr);
        lastGroup = stat.group;
      }

      const pts = stat.type === "select" ? stat.options[0].pts : stat.pts;
      const count = getStatValue(stat.key, "count", stat.def);

      const tr = document.createElement("tr");
      tr.dataset.key = stat.key;

      const tdName = document.createElement("td");
      tdName.className = "stat-name";
      tdName.textContent = stat.label;
      if (stat.note){
        const small = document.createElement("div");
        small.className = "stat-note";
        small.textContent = stat.note;
        tdName.appendChild(small);
      }
      tr.appendChild(tdName);

      if (stat.type === "select"){
        const tdSel = document.createElement("td");
        tdSel.colSpan = 2;
        const sel = document.createElement("select");
        sel.className = "finish-select";
        sel.dataset.field = "select";
        stat.options.forEach((opt, i) => {
          const o = document.createElement("option");
          o.value = opt.pts;
          o.textContent = `${opt.label} (${opt.pts} ${pluralPt(opt.pts)})`;
          if (opt.pts === pts) o.selected = true;
          sel.appendChild(o);
        });
        tdSel.appendChild(sel);
        tr.appendChild(tdSel);
      } else {
        const tdPts = document.createElement("td");
        tdPts.className = "center";
        const ptsStatic = document.createElement("span");
        ptsStatic.className = "pts-static";
        ptsStatic.textContent = fmtNum(pts) + " " + pluralPt(pts);
        ptsStatic.title = "Fixed reference value — not editable";
        tdPts.appendChild(ptsStatic);
        tr.appendChild(tdPts);

        const tdCount = document.createElement("td");
        tdCount.className = "center";
        const countInput = document.createElement("input");
        countInput.type = "number"; countInput.step = "1"; countInput.className = "count-input";
        countInput.value = count; countInput.dataset.field = "count";
        tdCount.appendChild(countInput);
        tr.appendChild(tdCount);
      }

      const tdSub = document.createElement("td");
      const subSpan = document.createElement("span");
      subSpan.className = "sub-val";
      tdSub.appendChild(subSpan);
      tr.appendChild(tdSub);

      body.appendChild(tr);
    });

    body.oninput = (e) => {
      const target = e.target;
      const tr = target.closest("tr");
      if (!tr || !tr.dataset.key) return;
      const key = tr.dataset.key;

      if (target.dataset.field === "select"){
        setStatValue(key, "pts", parseFloat(target.value));
        setStatValue(key, "count", 1);
      } else if (target.dataset.field === "count"){
        const val = parseFloat(target.value);
        setStatValue(key, target.dataset.field, isNaN(val) ? 0 : val);
      } else {
        return;
      }
      recompute();
    };

    recompute();
  }

  // ---------- Compute + spiel ----------
  function recompute(){
    const stats = getStats();
    const body = document.getElementById("statBody");
    const rows = body.querySelectorAll("tr[data-key]");
    let total = 0;
    const lineData = [];

    rows.forEach(tr => {
      const key = tr.dataset.key;
      const stat = stats.find(s => s.key === key);
      const defaultPts = stat.type === "select" ? stat.options[0].pts : stat.pts;
      const pts = stat.type === "select" ? getStatValue(key, "pts", defaultPts) : defaultPts;
      const count = getStatValue(key, "count", stat.def);
      const subtotal = pts * count;
      total += subtotal;

      const subSpan = tr.querySelector(".sub-val");
      subSpan.textContent = (subtotal > 0 ? "+" : "") + fmtNum(subtotal) + " pts";
      subSpan.className = "sub-val " + (subtotal > 0 ? "pos" : subtotal < 0 ? "neg" : "zero");

      const includeAll = !!getSport().showAllInSpiel;
      if (count !== 0 || includeAll){
        const label = stat.type === "select"
          ? (stat.options.find(o => o.pts === pts) || {}).label || stat.label
          : stat.label;
        lineData.push({label, pts, count, subtotal, isSelect: stat.type === "select"});
      }
    });

    total = Math.round(total * 100) / 100;
    renderSpielBody(lineData, total);
    renderSpielTag();

    const totalEl = document.getElementById("totalNum");
    totalEl.textContent = fmtNum(total) + " pts";
    totalEl.classList.add("bump");
    setTimeout(() => totalEl.classList.remove("bump"), 180);

    document.getElementById("rawText").value = buildRawText(lineData, total);
  }

  function renderSpielBody(lineData, total){
    const body = document.getElementById("spielBody");
    body.innerHTML = "";
    if (lineData.length === 0){
      const p = document.createElement("p");
      p.className = "spiel-empty";
      p.textContent = "Enter stat counts on the left to build the spiel.";
      body.appendChild(p);
      return;
    }
    lineData.forEach(l => {
      const row = document.createElement("div");
      row.className = "spiel-line";
      const left = document.createElement("span");
      left.textContent = l.isSelect
        ? `${l.label} =`
        : `${l.label}: ${fmtNum(l.pts)} ${pluralPt(l.pts)} × ${fmtNum(l.count)} =`;
      const right = document.createElement("span");
      right.className = "amt " + (l.subtotal > 0 ? "pos" : l.subtotal < 0 ? "neg" : "");
      right.textContent = `${fmtNum(l.subtotal)} ${pluralPt(l.subtotal)}`;
      row.appendChild(left); row.appendChild(right);
      body.appendChild(row);
    });
  }

  function buildRawText(lineData, total){
    const header = `${getSport().name}${currentLeagueLabel() && currentLeagueLabel() !== getSport().name ? " — " + currentLeagueLabel() : ""} Fantasy Score`;
    let lines = [header, ""];
    if (lineData.length === 0){
      lines.push("(no stats entered)");
    } else {
      lineData.forEach(l => {
        lines.push(l.isSelect
          ? `${l.label} = ${fmtNum(l.subtotal)} ${pluralPt(l.subtotal)}`
          : `${l.label}: ${fmtNum(l.pts)} ${pluralPt(l.pts)} × ${fmtNum(l.count)} = ${fmtNum(l.subtotal)} ${pluralPt(l.subtotal)}`);
      });
    }
    lines.push("");
    lines.push(`✅ Total FS = ${fmtNum(total)} pts`);
    return lines.join("\n");
  }

  // ---------- Wire up static controls ----------
  function wireStatic(){
    document.getElementById("copyBtn").onclick = async () => {
      const text = document.getElementById("rawText").value;
      try {
        await navigator.clipboard.writeText(text);
      } catch(e){
        const ta = document.getElementById("rawText");
        ta.classList.add("show"); ta.select(); document.execCommand("copy");
      }
      const btn = document.getElementById("copyBtn");
      const original = btn.textContent;
      btn.textContent = "Copied ✓";
      btn.classList.add("copied");
      setTimeout(() => { btn.textContent = original; btn.classList.remove("copied"); }, 1400);
    };

    document.getElementById("textBtn").onclick = () => {
      document.getElementById("rawText").classList.toggle("show");
    };

    const searchInput = document.getElementById("sportSearch");
    const searchBtn = document.getElementById("sportSearchBtn");

    function chipMatches(chip, q){
      if (chip.textContent.toLowerCase().includes(q)) return true;
      const sport = SPORTS[chip.dataset.key];
      if (sport && sport.aliases){
        return sport.aliases.some(a => a.toLowerCase().includes(q));
      }
      return false;
    }

    function applySportFilter(){
      const q = searchInput.value.trim().toLowerCase();
      const chips = document.querySelectorAll("#sportRail .chip");
      chips.forEach(chip => {
        chip.classList.remove("search-dim", "search-hit");
        if (!q) return;
        const match = chipMatches(chip, q);
        chip.classList.add(match ? "search-hit" : "search-dim");
      });
    }

    function jumpToFirstMatch(){
      const q = searchInput.value.trim().toLowerCase();
      if (!q) return;
      const chips = Array.from(document.querySelectorAll("#sportRail .chip"));
      const hit = chips.find(chip => chipMatches(chip, q) && !chip.classList.contains("active"))
        || chips.find(chip => chipMatches(chip, q));
      if (hit){
        hit.scrollIntoView({behavior: "smooth", inline: "center", block: "nearest"});
        hit.click();
        searchInput.value = "";
        applySportFilter();
      }
    }

    searchInput.oninput = applySportFilter;
    searchInput.onkeydown = (e) => { if (e.key === "Enter") jumpToFirstMatch(); };
    searchBtn.onclick = jumpToFirstMatch;

    document.getElementById("openRef").onclick = openRefModal;
    document.getElementById("closeRef").onclick = () => {
      document.getElementById("refModal").classList.remove("show");
    };
    document.getElementById("refModal").addEventListener("click", (e) => {
      if (e.target.id === "refModal") document.getElementById("refModal").classList.remove("show");
    });
  }

  function renderAll(){
    renderRail();
    renderControls();
    renderRefButton();
    renderStatTable();
    renderSpielTag();
  }

  const sport0 = getSport();
  if (sport0.modes) currentMode = sport0.modes[0];
  wireStatic();
  renderAll();
})();

